import test from 'node:test';
import assert from 'node:assert/strict';
import {DatabaseSync} from 'node:sqlite';
import {mkdtemp,rm,chmod,readFile} from 'node:fs/promises';
import {tmpdir} from 'node:os';
import {join} from 'node:path';
import {classifyStageContent,createStreamingStageAssessment} from '../tools/capacity/streaming-stage-assessment.mjs';
const content=classifyStageContent({type:'response.output_text.delta',item_id:'synthetic-item',output_index:0,delta:'synthetic content'});
const tick=(base,ms)=>String(base+BigInt(Math.round(ms*1e6)));
async function fixture(t,options={}){
  const directory=await mkdtemp(join(tmpdir(),'harbor-stage-collector-'));await chmod(directory,0o700);const file=join(directory,'history.sqlite'),db=new DatabaseSync(file);await chmod(file,0o600);db.exec('CREATE TABLE traces(trace TEXT PRIMARY KEY,state TEXT NOT NULL)');t.after(async()=>{db.close();await rm(directory,{recursive:true,force:true});});let unavailable=false,open=true;
  const history={lookup:trace=>unavailable?'unavailable':db.prepare('SELECT state FROM traces WHERE trace=?').get(trace)?.state??'absent',begin:trace=>{if(unavailable)return 'unavailable';return db.prepare("INSERT INTO traces VALUES(?,'active') ON CONFLICT DO NOTHING").run(trace).changes?'stored':'duplicate';},finalize:trace=>{if(unavailable)return 'unavailable';if(db.prepare("UPDATE traces SET state='final' WHERE trace=? AND state='active'").run(trace).changes)return 'stored';return history.lookup(trace)==='final'?'duplicate':'unavailable';}};
  const proofs=new WeakMap(),sourceProofs={},referenceClock={kernelId:'owned-test-kernel'},topologyProof=Object.freeze({});
  for(const role of ['gateway','upstream','client','reader']){sourceProofs[role]=Object.freeze({});proofs.set(sourceProofs[role],{role,bound:role==='client'?(options.clientBound??'exact'):undefined,endpoint:role==='client'?(options.clientEndpoint??'helper-delivery'):undefined,clock:{kind:'linux-hrtime-ns',kernelId:'owned-test-kernel',clockId:role+'-clock',epoch:'epoch-1',...(options.clocks?.[role]??{})},isOpen:()=>open});}
  const collector=createStreamingStageAssessment({referenceClock,history,profile:'selfcheck',minSamples:1,verifySource:({role,proof})=>proofs.get(proof)?.role===role?proofs.get(proof):null,verifyTopology:proof=>proof===topologyProof?{realHelper:true,tls:true,lan:true,proxyPreserved:true,...options.topology}:null,topologyProof,...options});
  const sources=Object.fromEntries(Object.entries(sourceProofs).map(([role,proof])=>[role,collector.source({role,proof})]));
  const emit=(role,trace,base,type,ms,extra={})=>sources[role].observe({trace,type,atNs:tick(base,ms),...extra});
  const run=(trace,base=1000000000000n,config={})=>{
    const group=config.group??'normal',firstReceive=config.firstReceive??42,middleReceive=Math.max(config.middleReceive??63,firstReceive+1),clientFinish=config.clientEnd??Math.max(105,firstReceive+1,middleReceive+1);collector.begin({trace,group});if(!config.omitPolicy)emit('gateway',trace,base,'accepted',config.acceptedAt??2,{accepted:config.accepted??true,recordingExpected:config.recordingExpected??true});const body=config.body??0,dispatch=config.dispatch??20;
    emit('gateway',trace,base,'body-end',body);emit('gateway',trace,base,'admission-attempt',1);emit('gateway',trace,base,'admission-granted',2);
    for(const [start,end,queued=true] of config.waits??[[10,15]])emit('gateway',trace,base,'wait',end,{startNs:tick(base,start),endNs:tick(base,end),queued,queue:'handoff',outcome:'granted'});
    if(!config.omitLeases)for(const lease of ['execution','output','body','member'])emit('gateway',trace,base,'lease',config.acquireAt??3,{lease,action:'acquire'});
    if(!config.omitDispatch)emit('gateway',trace,base,'dispatch',dispatch);
    for(const [ordinal,sourceAt,receivedAt] of [[0,config.firstSource??40,firstReceive],[1,config.middleSource??60,middleReceive]]){
      emit('gateway',trace,base,'content',sourceAt,{ordinal,...content});emit('client',trace,base,'content',receivedAt,{ordinal,...content});
    }
    if(config.clientCancelAt!==undefined)emit('client',trace,base,'cancel',config.clientCancelAt);if(config.cancel){if(!config.omitGatewayCancel)emit('gateway',trace,base,'cancel',config.gatewayCancelAt??65);if(!config.omitUpstreamCancel)emit('upstream',trace,base,'cancel',config.upstreamCancelAt??70);}
    emit('upstream',trace,base,'end',config.upstreamEnd??90,{outcome:config.outcome??'ok'});
    if(!config.omitLeases)for(const [index,lease] of ['execution','output','body','member'].entries())emit('gateway',trace,base,'lease',lease==='execution'&&config.earlyExecution?80:(config.releaseBase??100)+index,{lease,action:'release'});
    emit('client',trace,base,'end',clientFinish,{outcome:config.outcome??'ok'});
    if(!config.omitVisibility)for(const projection of config.projections??['body','usage']){
      if(!config.omitWatch)emit('reader',trace,base,'watch-start',config.watchAt??clientFinish+1,{projection});if(!config.lateFirstRead)emit('reader',trace,base,'visibility',clientFinish+6,{projection,queryStartNs:tick(base,clientFinish+5),ready:false,readVerified:false});
      const at=config.lateFirstRead?clientFinish+20001:clientFinish+16;emit('reader',trace,base,'visibility',at,{projection,queryStartNs:tick(base,at-1),ready:true,readVerified:true});
    }
    if(config.finalize!==false)collector.finalize(trace);return collector.collect();
  };
  return {collector,history,sources,sourceProofs,proofs,topologyProof,referenceClock,run,emit,db,file,setUnavailable:value=>unavailable=value,setOpen:value=>open=value};
}
test('all real endpoint categories have a reachable true branch using a persistent trace history',async t=>{
  const f=await fixture(t);f.run('normal');const result=f.run('cancelled',1001000000000n,{group:'cancel',outcome:'cancelled',cancel:true});assert.equal(result.passed,true,JSON.stringify(result));assert.equal(result.formalEligible,false);for(const key of ['requestStages','streamRelay','cancelRelease','bodyVisibility'])assert.equal(result[key].passed,true);assert.equal(result.metrics.preDispatch.upper.p95,15);assert.equal(result.metrics.firstRelay.upper.p95,2);assert.equal(result.metrics.middleRelay.upper.p95,3);assert.equal(result.metrics.bodyVisibility.lower.p95,5);assert.equal(result.metrics.bodyVisibility.upper.p95,16);assert.equal(result.metrics.cancelPropagation.upper.max,5);assert.equal(result.counts.active,0);assert.equal(f.db.prepare('SELECT COUNT(*) n FROM traces').get().n,2);
});
test('one classifier excludes heartbeat and model timestamps, matches text/tool content and bounds full output inspection',()=>{
  assert.equal(classifyStageContent({type:'heartbeat',capacity_sent_wall_ms:1}),null);assert.equal(classifyStageContent({type:'response.created'}),null);assert.equal(classifyStageContent({type:'response.output_text.delta',delta:''}),null);
  const a=classifyStageContent({type:'response.output_text.delta',delta:'actual',capacity_sent_wall_ms:1}),b=classifyStageContent({type:'response.output_text.delta',delta:'actual',capacity_sent_wall_ms:999999});assert.deepEqual(a,b);assert.equal(classifyStageContent({type:'response.function_call_arguments.delta',delta:'{"x":1}'}).contentKind,'arguments');assert.equal(classifyStageContent({type:'response.completed',response:{status:'completed',output:[{type:'message',content:[{text:'actual'}]}]}}).contentKind,'terminal');assert.equal(classifyStageContent({type:'response.completed',response:{status:'completed',output:[{type:'message',content:Array(4).fill({text:''})}]}},{maxItems:3}).incomplete,true);assert.equal(classifyStageContent({type:'response.output_text.delta',delta:'large'},{maxBytes:2}).incomplete,true);
});
test('queue deductions clip to complete-body through dispatch and merge overlaps; immediate binds are not deducted',async t=>{
  const f=await fixture(t);const result=f.run('queue',1000000000000n);assert.equal(result.metrics.preDispatch.upper.p95,15);
  const g=await fixture(t);const observed=g.run('overlap',1000000000000n,{body:10,dispatch:50,waits:[[0,8],[15,25],[20,40],[10,50,false]]});assert.equal(observed.metrics.preDispatch.lower.p95,15);assert.equal(observed.metrics.preDispatch.upper.p95,15);
});
test('a missing helper, TLS, LAN or proxy proof cannot be replaced by client endpoint claims',async t=>{
  for(const feature of ['realHelper','tls','lan','proxyPreserved']){const f=await fixture(t,{topology:{[feature]:false}});f.run('normal');const result=f.run('cancel',1001000000000n,{group:'cancel',outcome:'cancelled',cancel:true});assert.equal(result.passed,null);assert.equal(result.streamRelay.passed,null);assert.ok(result.missing.includes('helper_tls_lan_proxy_unproven'));}
  const f=await fixture(t);f.collector.begin({trace:'forged'});assert.equal(f.emit('client','forged',1000000000000n,'dispatch',2),false);assert.equal(f.collector.collect().passed,false);assert.ok(f.collector.collect().issues.some(row=>row.code==='source_endpoint_rejected'));const unproven=f.collector.source({role:'gateway',proof:{}});assert.equal(unproven.observe({trace:'forged',type:'dispatch',atNs:'1'}),false);assert.ok(f.collector.collect().missing.includes('source_unproven'));
});
test('unmapped, expired, inconsistent and closed source epochs stay unknown without breaking observed calls',async t=>{
  const clocks=[{kernelId:'another-kernel'},{kernelId:'another-kernel',mapping:{referenceKernelId:'owned-test-kernel',lowerOffsetNs:'0',upperOffsetNs:'1',validFromNs:'0',validUntilNs:'2'}},{kernelId:'another-kernel',mapping:{referenceKernelId:'owned-test-kernel',lowerOffsetNs:'2',upperOffsetNs:'1',validFromNs:'0',validUntilNs:'999999999999999'}}];
  for(const clock of clocks){const f=await fixture(t,{clocks:{gateway:clock}});const result=f.run('unknown-clock');assert.notEqual(result.passed,true);assert.ok(result.missing.includes('clock_mapping_unproven'));}
  const f=await fixture(t);f.collector.begin({trace:'closed-epoch'});f.setOpen(false);assert.equal(f.emit('gateway','closed-epoch',1000000000000n,'body-end',0),false);assert.ok(f.collector.collect().missing.includes('source_epoch_closed'));
});
test('conservative bounds distinguish proof of passing, proof of failure and an interval crossing a threshold',async t=>{
  const mapping={referenceKernelId:'owned-test-kernel',lowerOffsetNs:'0',upperOffsetNs:'2000000',validFromNs:'0',validUntilNs:'9999999999999999'};
  const uncertain=await fixture(t,{clocks:{gateway:{kernelId:'other',mapping}}});const ambiguous=uncertain.run('uncertain',1000000000000n,{firstReceive:91,middleReceive:111});assert.equal(ambiguous.metrics.firstRelay.lower.p95,49);assert.equal(ambiguous.metrics.firstRelay.upper.p95,51);assert.equal(ambiguous.metrics.firstRelay.passed,null);
  const bad=await fixture(t);assert.equal(bad.run('slow',1000000000000n,{firstReceive:1000}).streamRelay.passed,false);const boundary=await fixture(t);assert.equal(boundary.run('boundary',1000000000000n,{firstReceive:90.001}).metrics.firstRelay.passed,null);
});
test('upstream completion does not impose an inverse order on buffered gateway content or already released leases',async t=>{
  const f=await fixture(t);const delayed=f.run('buffered-content',1000000000000n,{upstreamEnd:50});assert.equal(delayed.issueCount,0);assert.equal(delayed.metrics.firstRelay.passed,true);assert.equal(delayed.metrics.middleRelay.passed,true);
  const before=await fixture(t);const released=before.run('already-released',1000000000000n,{releaseBase:70});assert.equal(released.issueCount,0);assert.equal(released.metrics.release.lower.max,0);assert.equal(released.metrics.release.upper.max,0);assert.equal(released.metrics.release.passed,true);
  const mixed=await fixture(t);const result=mixed.run('one-early-release',1000000000000n,{earlyExecution:true});assert.equal(result.issueCount,0);assert.equal(result.metrics.release.upper.max,13,'other leases still determine the final release delay');
});
test('real lease order violations and release beyond five seconds remain failures',async t=>{
  for(const [name,config,code] of [['release-before-acquire',{releaseBase:1},'lease_release_before_acquire'],['acquire-after-dispatch',{acquireAt:30},'lease_acquired_after_dispatch'],['content-before-dispatch',{firstSource:10},'content_before_dispatch']]){const f=await fixture(t);const result=f.run(name,1000000000000n,config);assert.equal(result.passed,false);assert.ok(result.issues.some(row=>row.code===code),JSON.stringify(result.issues));}
  const slow=await fixture(t);const result=slow.run('slow-release',1000000000000n,{releaseBase:5200});assert.equal(result.metrics.release.passed,false);assert.ok(result.metrics.release.lower.max>5000);
});
