  const f=await fixture(t,{minSamples:2});f.run('slow-window',1000000000000n,{firstReceive:1000});for(let i=0;i<120;i++)f.run('fast-'+i,1500000000000n+BigInt(i)*1000000n);const result=f.collector.collect();assert.equal(result.metrics.firstRelay.upper.p99,2);assert.equal(result.metrics.firstRelay.passed,false);assert.equal(result.streamRelay.passed,false);
