test('late and duplicate content remains detectable after many finalized traces without growing active memory',async t=>{
  const f=await fixture(t,{maxActive:2});for(let i=0;i<180;i++)f.run('history-'+i,1000000000000n+BigInt(i)*1000000n);assert.equal(f.collector.collect().counts.active,0);assert.equal(f.collector.collect().counts.peakActive,1);assert.equal(f.db.prepare("SELECT COUNT(*) n FROM traces WHERE state='final'").get().n,180);assert.equal(f.emit('client','history-0',1000000000000n,'content',42,{ordinal:0,...content}),false);assert.equal(f.collector.collect().passed,false);assert.ok(f.collector.collect().issues.some(row=>row.code==='late_stage_event'));assert.equal(f.collector.begin({trace:'history-0'}),false);assert.ok(f.collector.collect().issues.some(row=>row.code==='duplicate_stage_trace'));
  const bytes=await readFile(f.file);assert.equal(bytes.includes(Buffer.from('synthetic content')),false);
});
