test('a long stream late middle-content window cannot be diluted by its early fast fragments',async t=>{
  const base=1000000000000n;
  const g=await fixture(t);g.collector.begin({trace:'continuous'});g.emit('gateway','continuous',base,'accepted',2,{accepted:true,recordingExpected:true});g.emit('gateway','continuous',base,'body-end',0);g.emit('gateway','continuous',base,'dispatch',20);g.emit('gateway','continuous',base,'admission-attempt',1);g.emit('gateway','continuous',base,'admission-granted',2);for(const lease of ['execution','output','body','member'])g.emit('gateway','continuous',base,'lease',3,{lease,action:'acquire'});for(let ordinal=0;ordinal<150;ordinal++){g.emit('gateway','continuous',base,'content',40+ordinal,{ordinal,...content});g.emit('client','continuous',base,'content',42+ordinal,{ordinal,...content});}
  g.emit('gateway','continuous',base,'content',400000,{ordinal:150,...content});g.emit('client','continuous',base,'content',401000,{ordinal:150,...content});g.emit('upstream','continuous',base,'end',500000,{outcome:'ok'});for(const lease of ['execution','output','body','member'])g.emit('gateway','continuous',base,'lease',500010,{lease,action:'release'});g.emit('client','continuous',base,'end',500020,{outcome:'ok'});for(const projection of ['body','usage']){g.emit('reader','continuous',base,'watch-start',500021,{projection});g.emit('reader','continuous',base,'visibility',500025,{projection,queryStartNs:tick(base,500024),ready:true,readVerified:true});}g.collector.finalize('continuous');const result=g.collector.collect();assert.equal(result.incomplete,false);assert.equal(result.metrics.middleRelay.upper.p99,2);assert.equal(result.metrics.middleRelay.passed,false);assert.ok(result.windows.some(window=>window.metrics['normal:middleRelay']?.passed===false));
});
